// ------------------------------------------------------------------
// QueryBuilder – every method returns the builder itself (for chaining)
// ------------------------------------------------------------------
class QueryBuilder {
  constructor(table) {
    this.table = table;
    this.filters = [];
    this.action = null;        // 'select','insert','update','delete','upsert'
    this.payload = null;
    this._head = false;
    this._count = false;
    this._limit = null;
    this._single = false;
    this._order = null;       // { col, ascending }
  }

  // ---- chainable methods ----
  select(cols, opts) {
    this.action = 'select';
    if (opts?.count === 'exact') {
      this._count = true;
      if (opts.head) this._head = true;
    }
    return this;
  }
  insert(data) {
    this.action = 'insert';
    this.payload = data;
    // execute immediately, but keep a reference to the result
    const result = this._execute();
    // add .select() and .single() for compatibility
    result.select = () => this; // safe
    result.single = () => (this.payload ? thenable({ data: (Array.isArray(this.payload) ? this.payload[0] : this.payload) || null, error: null }) : thenable({ data: null, error: null }));
    return result;
  }
  update(data) {
    this.action = 'update';
    this.payload = data;
    return this; // wait for .eq()/.in()
  }
  delete() {
    this.action = 'delete';
    return this; // wait for .eq()
  }
  upsert(data) {
    this.action = 'upsert';
    this.payload = data;
    return this._execute(); // upsert executes immediately
  }

  eq(col, val) {
    this.filters.push({ type: 'eq', col, val });
    return this;
  }
  gte(col, val) {
    this.filters.push({ type: 'gte', col, val });
    return this;
  }
  lte(col, val) {
    this.filters.push({ type: 'lte', col, val });
    return this;
  }
  not(col, val) {
    this.filters.push({ type: 'not', col, val });
    return this;
  }
  is(col, val) {
    this.filters.push({ type: 'is', col, val });
    return this;
  }
  order(col, opts = {}) {
    this._order = { col, ascending: opts.ascending !== false };
    return this._execute(); // order typically ends the chain
  }
  limit(n) {
    this._limit = n;
    return this._execute();
  }
  single() {
    this._single = true;
    return this._execute();
  }
  maybeSingle() {
    return this.single(); // alias
  }
  in(col, vals) {
    // For .in() we add a filter that checks if the value is in the vals array
    this.filters.push({ type: 'in', col, vals });
    return this;
  }

  // ---- terminal resolution (then/catch) ----
  then(resolve) {
    resolve(this._execute());
  }
  catch(fn) {
    // ignore
    return this;
  }

  // ---- execution logic ----
  _applyFilters(list) {
    return list.filter(r =>
      this.filters.every(f => {
        try {
          if (f.type === 'eq') return r[f.col] === f.val;
          if (f.type === 'gte') return new Date(r[f.col]) >= new Date(f.val);
          if (f.type === 'lte') return new Date(r[f.col]) <= new Date(f.val);
          if (f.type === 'not') return r[f.col] !== f.val;
          if (f.type === 'is') return r[f.col] === null || r[f.col] === undefined;
          if (f.type === 'in') return f.vals.includes(r[f.col]);
          return true;
        } catch { return false; }
      })
    );
  }

  _execute() {
    const rows = load(this.table);

    if (this.action === 'select') {
      let list = this._applyFilters(rows);
      if (this._order) {
        const { col, ascending } = this._order;
        list.sort((a, b) => (a[col] > b[col] ? 1 : -1) * (ascending ? 1 : -1));
      }
      if (this._limit !== null) {
        list = list.slice(0, this._limit);
      }
      if (this._single) {
        return thenable({ data: list[0] || null, error: null });
      }
      if (this._count) {
        const total = this._applyFilters(rows).length;
        return thenable({ count: total, data: this._head ? [] : list, error: null });
      }
      return thenable({ data: list, error: null });
    }

    if (this.action === 'insert') {
      const arr = Array.isArray(this.payload) ? this.payload : [this.payload];
      const newRows = arr.map(d => ({ id: genID(), ...d }));
      save(this.table, [...rows, ...newRows]);
      const res = thenable({ data: newRows, error: null });
      res.select = () => thenable({ data: newRows, error: null });
      res.single = () => thenable({ data: newRows[0] || null, error: null });
      return res;
    }

    if (this.action === 'update') {
      try {
        const updated = rows.map(r =>
          this.filters.every(f => r[f.col] === f.val) ? { ...r, ...this.payload } : r
